#!/usr/bin/env python3
"""Evaluate the versioned fixed scenario set using actual structured evidence."""
import argparse,pathlib,json,hashlib
P=pathlib.Path;p=argparse.ArgumentParser();p.add_argument('--source',type=P,required=True);p.add_argument('--evidence',type=P,required=True);n=p.parse_args();r=n.evidence;src=n.source.resolve()
def read(p):return json.loads(p.read_text())
sources={k:read(r/k/'results.json') for k in ['final_story','final_business','final_acceptance','final_content_faults','final_story_faults']};scale=read(r/'final_scale/scale_samples.json')
mapping=[('daily_dialogue','final_story','ordinary_conversation_and_numeric_quotes'),('finite_resources','final_business','accounts_scale_transfer_budget_and_quantum'),('cross_role_secret','final_story','multi_role_context_cache_report_and_error_isolation'),('long_commitment','final_story','unified_consequence_timeline_real_advance_and_expiry'),('goal_conflict','final_story','independent_scenes_focus_and_existing_patrol_policy'),('expired_event','final_story','unified_consequence_timeline_real_advance_and_expiry'),('unknown_accounting','final_business','scheduler_business_and_unknown_resolver_barriers'),('old_instance_after_content_update','final_acceptance','real_install_two_upgrades_and_old_instance_compatibility')]
rows=[]
for scenario,group,name in mapping:
 test=next(t for t in sources[group]['tests'] if t['name']==name);rows.append({'scenario':scenario,'mechanical_and_permission_result':test['status'],'evidence':group+'/results.json#'+name,'narrative_quality':'NOT_RUN','human_rubric':['motivation from known goals','character differentiation from sourced traits','causality and continuity','visible effect of actual player choice'],'human_score':None})
rows.append({'scenario':'long_history_retrieval','mechanical_and_permission_result':'PASS' if scale['status']=='PASS' and len(scale['profiles'])==3 else 'FAIL','evidence':'final_scale/scale_samples.json','narrative_quality':'NOT_RUN','human_score':None})
xp=read(r/'final_acceptance/fixed_strategy_eval.json');summary={'schema':'FIXED_EVALUATION_SET_V1','status':'PASS' if all(x['mechanical_and_permission_result']=='PASS' for x in rows) else 'FAIL','source_identity':{'save_set_id':read(src/'manifest.json')['save_set_id'],'manifest_sha256':hashlib.sha256((src/'manifest.json').read_bytes()).hexdigest(),'engine_sha256':hashlib.sha256((src/'engine.py').read_bytes()).hexdigest()},'initial_conditions':'each named fixture clones the bound formal source; exact actions/IDs in bundled scripts; random seed/cycles never changed to pass tests','scenarios':rows,'experience_effect':{'fixed_rank_recall_at_1_before':xp['retrieval_recall_at_1_before'],'fixed_rank_recall_at_1_after':xp['retrieval_recall_at_1_after'],'interpretation':'synthetic deterministic ranking only, not measured model error reduction','model_generation':'NOT_RUN'},'model_identity':None,'model_prompt_parameters':None}
(r/'fixed_evaluation.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2));print(json.dumps({'status':summary['status'],'scenarios':len(rows)}));raise SystemExit(0 if summary['status']=='PASS' else 1)
